port('bottle-song','char *recite(unsigned start,unsigned take);',String.raw`char*recite(unsigned start,unsigned take){const char*n[]={"no","one","two","three","four","five","six","seven","eight","nine","ten"};char*out=(char*)calloc(5000,1);if(start>10||start<take)return out;for(unsigned i=start;i>start-take;i--){if(i<start)strcat(out,"\n\n");char word[20];strcpy(word,n[i]);word[0]=(char)toupper((unsigned char)word[0]);sprintf(out+strlen(out),"%s green bottle%s hanging on the wall,\n%s green bottle%s hanging on the wall,\nAnd if one green bottle should accidentally fall,\nThere'll be %s green bottle%s hanging on the wall.",word,i==1?"":"s",word,i==1?"":"s",n[i-1],i==2?"":"s");}return out;}`,String.raw`char*s=recite(1,1);assert(!strcmp(s,"One green bottle hanging on the wall,\nOne green bottle hanging on the wall,\nAnd if one green bottle should accidentally fall,\nThere'll be no green bottles hanging on the wall."));free(s);s=recite(2,2);assert(strstr(s,"There'll be one green bottle")&&strstr(s,"\n\nOne"));free(s);`,String.raw`char*recite(unsigned a,unsigned b){(void)a;(void)b;return (char*)calloc(1,1);}`);
