port('killer-sudoku-helper','size_t combinations(int target,unsigned size,unsigned excluded_mask,unsigned *out);',String.raw`size_t combinations(int target,unsigned size,unsigned excluded,unsigned*out){size_t n=0;for(unsigned m=0;m<512;m++){if(m&excluded)continue;int sum=0;unsigned count=0;for(unsigned i=0;i<9;i++)if(m&(1u<<i)){sum+=(int)i+1;count++;}if(sum==target&&count==size)out[n++]=m;}for(size_t i=0;i<n;i++)for(size_t j=i+1;j<n;j++){unsigned a=out[i],b=out[j];for(unsigned k=0;k<9;k++)if((a&(1u<<k))!=(b&(1u<<k))){if(b&(1u<<k)){out[i]=b;out[j]=a;}break;}}return n;}`,String.raw`unsigned o[512];assert(combinations(10,2,0,o)==4);assert(o[0]==((1u<<0)|(1u<<8)));assert(combinations(10,2,1,o)==3);assert(combinations(45,9,0,o)==1&&o[0]==511);assert(combinations(1,2,0,o)==0);assert(combinations(0,0,0,o)==1&&o[0]==0);`,String.raw`size_t combinations(int t,unsigned s,unsigned e,unsigned*o){(void)t;(void)s;(void)e;(void)o;return 0;}`);
port('dominoes','typedef struct {int left,right;} domino;\nbool chain(const domino *input,size_t n,domino *out);',String.raw`static bool search(const domino*d,size_t n,bool*used,domino*out,size_t k,int first,int last){if(k==n)return first==last;for(size_t i=0;i<n;i++)if(!used[i]){for(int flip=0;flip<2;flip++){int a=flip?d[i].right:d[i].left,b=flip?d[i].left:d[i].right;if(k&&a!=last)continue;used[i]=true;out[k].left=a;out[k].right=b;if(search(d,n,used,out,k+1,k?first:a,b))return true;used[i]=false;}}return false;}bool chain(const domino*d,size_t n,domino*out){if(!n)return true;bool*u=(bool*)calloc(n,sizeof(bool));bool ok=search(d,n,u,out,0,0,0);free(u);return ok;}`,String.raw`domino a[]={{1,2},{3,1},{2,3}},o[3];assert(chain(a,3,o));for(int i=0;i<3;i++)assert(o[i].right==o[(i+1)%3].left);domino b[]={{1,2},{2,3}};assert(!chain(b,2,o));assert(chain(NULL,0,NULL));`,String.raw`bool chain(const domino*d,size_t n,domino*o){(void)d;(void)n;(void)o;return false;}`);
port('word-search','/* Word search coordinates are 1-based. */\ntypedef struct {size_t row,column;} coordinate;\nbool find_word(const char *const *grid,size_t rows,const char *word,coordinate *start,coordinate *end);',String.raw`bool find_word(const char*const*g,size_t rows,const char*w,coordinate*s,coordinate*e){size_t n=strlen(w);if(!n)return false;for(size_t r=0;r<rows;r++)for(size_t c=0;c<strlen(g[r]);c++)for(int dr=-1;dr<=1;dr++)for(int dc=-1;dc<=1;dc++){if(!dr&&!dc)continue;size_t k;for(k=0;k<n;k++){long rr=(long)r+(long)k*dr,cc=(long)c+(long)k*dc;if(rr<0||cc<0||(size_t)rr>=rows||(size_t)cc>=strlen(g[rr])||g[rr][cc]!=w[k])break;}if(k==n){s->row=r+1;s->column=c+1;e->row=(size_t)((long)r+(long)(n-1)*dr)+1;e->column=(size_t)((long)c+(long)(n-1)*dc)+1;return true;}}return false;}`,String.raw`const char*g[]={"abc","def","ghi"};coordinate a,b;assert(find_word(g,3,"aei",&a,&b)&&a.row==1&&b.row==3&&b.column==3);assert(find_word(g,3,"cba",&a,&b)&&a.column==3&&b.column==1);assert(find_word(g,3,"gda",&a,&b)&&a.row==3&&b.row==1);assert(!find_word(g,3,"zzz",&a,&b));`,String.raw`bool find_word(const char*const*g,size_t n,const char*w,coordinate*s,coordinate*e){(void)g;(void)n;(void)w;(void)s;(void)e;return false;}`);
port('rectangles','size_t count_rectangles(const char *const *grid,size_t rows);',String.raw`size_t count_rectangles(const char*const*g,size_t rows){size_t count=0;for(size_t r=0;r<rows;r++)for(size_t c=0;c<strlen(g[r]);c++)if(g[r][c]=='+')for(size_t x=c+1;x<strlen(g[r]);x++){if(g[r][x]!='-'&&g[r][x]!='+')break;if(g[r][x]!='+')continue;for(size_t y=r+1;y<rows;y++){if(strlen(g[y])<=x)break;if((g[y][c]!='|'&&g[y][c]!='+')||(g[y][x]!='|'&&g[y][x]!='+'))break;if(g[y][c]=='+'&&g[y][x]=='+'){bool ok=true;for(size_t k=c+1;k<x;k++)if(g[y][k]!='-'&&g[y][k]!='+')ok=false;if(ok)count++;}}}return count;}`,String.raw`const char*g[]={"+-+-+","| | |","+-+-+"};assert(count_rectangles(g,3)==3);const char*b[]={"+--+","|  |","+ -+"};assert(count_rectangles(b,3)==0);assert(count_rectangles(NULL,0)==0);`,String.raw`size_t count_rectangles(const char*const*g,size_t n){(void)g;(void)n;return 0;}`);
port('simple-linked-list','typedef struct node {int value;struct node *next;} node;\ntypedef struct {node *head;size_t length;} linked_list;\nvoid list_push(linked_list *list,int value);\nbool list_pop(linked_list *list,int *value);\nlinked_list list_reversed(const linked_list *list);\nvoid list_destroy(linked_list *list);',String.raw`void list_push(linked_list*l,int v){node*n=(node*)malloc(sizeof(node));n->value=v;n->next=l->head;l->head=n;l->length++;}bool list_pop(linked_list*l,int*v){if(!l->head)return false;node*n=l->head;*v=n->value;l->head=n->next;l->length--;free(n);return true;}linked_list list_reversed(const linked_list*l){linked_list r={NULL,0};for(node*n=l->head;n;n=n->next)list_push(&r,n->value);return r;}void list_destroy(linked_list*l){int v;while(list_pop(l,&v));}`,String.raw`linked_list l={NULL,0};int v;assert(!list_pop(&l,&v));list_push(&l,1);list_push(&l,2);list_push(&l,3);assert(l.length==3&&l.head->value==3);linked_list r=list_reversed(&l);assert(list_pop(&r,&v)&&v==1);assert(list_pop(&l,&v)&&v==3);list_destroy(&l);list_destroy(&r);assert(l.length==0);`,String.raw`void list_push(linked_list*l,int v){(void)l;(void)v;}bool list_pop(linked_list*l,int*v){(void)l;(void)v;return false;}linked_list list_reversed(const linked_list*l){(void)l;linked_list r={NULL,0};return r;}void list_destroy(linked_list*l){(void)l;}`);
port('matrix','typedef struct {size_t rows,cols;int *values;} matrix;\nbool matrix_parse(matrix *m,const char *text);\nsize_t matrix_row(const matrix *m,size_t index,int *out);\nsize_t matrix_column(const matrix *m,size_t index,int *out);\nvoid matrix_free(matrix *m);',String.raw`bool matrix_parse(matrix*m,const char*t){m->rows=0;m->cols=0;m->values=NULL;size_t cap=16,n=0,row=0;int*v=(int*)malloc(cap*sizeof(int));const char*p=t;while(*p){if(*p=='\n'){if(!row||(m->cols&&row!=m->cols)){free(v);return false;}m->cols=row;row=0;m->rows++;p++;continue;}if(isspace((unsigned char)*p)){p++;continue;}char*end;long x=strtol(p,&end,10);if(p==end){free(v);return false;}if(n==cap){cap*=2;v=(int*)realloc(v,cap*sizeof(int));}v[n++]=(int)x;row++;p=end;}if(row){if(m->cols&&row!=m->cols){free(v);return false;}m->cols=row;m->rows++;}m->values=v;return true;}size_t matrix_row(const matrix*m,size_t i,int*out){if(!i||i>m->rows)return 0;memcpy(out,m->values+(i-1)*m->cols,m->cols*sizeof(int));return m->cols;}size_t matrix_column(const matrix*m,size_t i,int*out){if(!i||i>m->cols)return 0;for(size_t r=0;r<m->rows;r++)out[r]=m->values[r*m->cols+i-1];return m->rows;}void matrix_free(matrix*m){free(m->values);m->values=NULL;}`,String.raw`matrix m;int o[10];assert(matrix_parse(&m,"1 2 3\n4 5 6"));assert(matrix_row(&m,2,o)==3&&o[0]==4&&o[2]==6);assert(matrix_column(&m,2,o)==2&&o[0]==2&&o[1]==5);assert(matrix_column(&m,4,o)==0);matrix_free(&m);assert(!matrix_parse(&m,"1 2\n3"));`,String.raw`bool matrix_parse(matrix*m,const char*t){(void)t;m->rows=m->cols=0;m->values=NULL;return false;}size_t matrix_row(const matrix*m,size_t i,int*o){(void)m;(void)i;(void)o;return 0;}size_t matrix_column(const matrix*m,size_t i,int*o){return matrix_row(m,i,o);}void matrix_free(matrix*m){free(m->values);}`);
port('affine-cipher','bool encode(const char *text,int a,int b,char *out);\nbool decode(const char *text,int a,int b,char *out);',String.raw`static int inverse(int a){a=(a%26+26)%26;for(int i=1;i<26;i++)if(a*i%26==1)return i;return -1;}static bool cipher(const char*t,int a,int b,char*out,bool enc){int inv=inverse(a);if(inv<0)return false;size_t n=0;for(;*t;t++){unsigned char c=(unsigned char)tolower((unsigned char)*t);if(!isalnum(c))continue;if(enc&&n&&n%5==0)*out++=' ';if(isalpha(c)){int x=enc?a*(c-'a')+b:inv*((c-'a')-b);c=(unsigned char)('a'+(x%26+26)%26);}*out++=(char)c;n++;}*out=0;return true;}bool encode(const char*t,int a,int b,char*out){return cipher(t,a,b,out,true);}bool decode(const char*t,int a,int b,char*out){return cipher(t,a,b,out,false);}`,String.raw`char o[200];assert(encode("yes",5,7,o)&&!strcmp(o,"xbt"));assert(encode("Testing,1 2 3, testing.",3,4,o)&&!strcmp(o,"jqgjc rw123 jqgjc rw"));assert(decode("xbt",5,7,o)&&!strcmp(o,"yes"));assert(!encode("test",6,17,o));`,String.raw`bool encode(const char*t,int a,int b,char*o){(void)t;(void)a;(void)b;*o=0;return false;}bool decode(const char*t,int a,int b,char*o){return encode(t,a,b,o);}`);
port('simple-cipher','bool cipher_key_valid(const char *key);\nbool cipher_encode(const char *key,const char *text,char *out);\nbool cipher_decode(const char *key,const char *text,char *out);\nvoid cipher_random_key(char *out,size_t length,uint64_t *state);',String.raw`bool cipher_key_valid(const char*k){if(!*k)return false;for(;*k;k++)if(*k<'a'||*k>'z')return false;return true;}static bool code(const char*k,const char*t,char*o,int sign){if(!cipher_key_valid(k))return false;size_t n=strlen(k);for(size_t i=0;t[i];i++)o[i]=(char)('a'+(t[i]-'a'+sign*(k[i%n]-'a')+26)%26);o[strlen(t)]=0;return true;}bool cipher_encode(const char*k,const char*t,char*o){return code(k,t,o,1);}bool cipher_decode(const char*k,const char*t,char*o){return code(k,t,o,-1);}void cipher_random_key(char*out,size_t n,uint64_t*s){for(size_t i=0;i<n;i++){*s=*s*6364136223846793005ULL+1;out[i]=(char)('a'+(*s>>32)%26);}out[n]=0;}`,String.raw`char o[200],d[200];assert(cipher_encode("abc","aaaaaaaa",o)&&!strcmp(o,"abcabcab"));assert(cipher_decode("abc",o,d)&&!strcmp(d,"aaaaaaaa"));assert(cipher_encode("z","z",o)&&!strcmp(o,"y"));assert(!cipher_key_valid("")&&!cipher_key_valid("ABC")&&!cipher_key_valid("abc1"));uint64_t seed=1;cipher_random_key(o,100,&seed);assert(strlen(o)==100&&cipher_key_valid(o));`,String.raw`bool cipher_key_valid(const char*k){(void)k;return false;}bool cipher_encode(const char*k,const char*t,char*o){(void)k;(void)t;*o=0;return false;}bool cipher_decode(const char*k,const char*t,char*o){return cipher_encode(k,t,o);}void cipher_random_key(char*o,size_t n,uint64_t*s){(void)n;(void)s;*o=0;}`);
