port('state-of-tic-tac-toe','typedef enum { INVALID=-1, ONGOING, DRAW, WIN } game_state;\ngame_state state(const char *const board[3]);',String.raw`static bool winner(const char*const*b,char c){for(int i=0;i<3;i++)if((b[i][0]==c&&b[i][1]==c&&b[i][2]==c)||(b[0][i]==c&&b[1][i]==c&&b[2][i]==c))return true;return (b[0][0]==c&&b[1][1]==c&&b[2][2]==c)||(b[0][2]==c&&b[1][1]==c&&b[2][0]==c);}game_state state(const char*const*b){int x=0,o=0;for(int r=0;r<3;r++){if(strlen(b[r])!=3)return INVALID;for(int c=0;c<3;c++){if(b[r][c]=='X')x++;else if(b[r][c]=='O')o++;else if(b[r][c]!=' ')return INVALID;}}bool wx=winner(b,'X'),wo=winner(b,'O');if(o>x||x>o+1||(wx&&wo)||(wx&&x!=o+1)||(wo&&x!=o))return INVALID;if(wx||wo)return WIN;return x+o==9?DRAW:ONGOING;}`,String.raw`const char*a[]={"XXX","OO ","   "};assert(state(a)==WIN);const char*b[]={"XOX","XXO","OXO"};assert(state(b)==DRAW);const char*c[]={"OOO","XX ","X  "};assert(state(c)==WIN);const char*d[]={"XXX","OOO","   "};assert(state(d)==INVALID);const char*e[]={"   ","   ","   "};assert(state(e)==ONGOING);`,String.raw`game_state state(const char*const*b){(void)b;return INVALID;}`);
