port('hangman','typedef enum { HANGMAN_ONGOING,HANGMAN_WIN,HANGMAN_LOSE } hangman_status;\ntypedef struct {char *word,*masked;bool guesses[256];int remaining;hangman_status status;} hangman;\nvoid hangman_init(hangman *g,const char *word);\nbool hangman_guess(hangman *g,unsigned char letter);\nvoid hangman_free(hangman *g);',String.raw`void hangman_init(hangman*g,const char*w){size_t n=strlen(w);g->word=(char*)malloc(n+1);strcpy(g->word,w);g->masked=(char*)malloc(n+1);memset(g->masked,'_',n);g->masked[n]=0;memset(g->guesses,0,sizeof g->guesses);g->remaining=9;g->status=HANGMAN_ONGOING;}bool hangman_guess(hangman*g,unsigned char c){if(g->status!=HANGMAN_ONGOING)return false;if(g->guesses[c]||!strchr(g->word,c))g->remaining--;g->guesses[c]=true;for(size_t i=0;g->word[i];i++)if(g->guesses[(unsigned char)g->word[i]])g->masked[i]=g->word[i];if(!strcmp(g->word,g->masked))g->status=HANGMAN_WIN;else if(g->remaining<0)g->status=HANGMAN_LOSE;return true;}void hangman_free(hangman*g){free(g->word);free(g->masked);}`,String.raw`hangman g;hangman_init(&g,"aba");assert(hangman_guess(&g,'a')&&!strcmp(g.masked,"a_a")&&g.remaining==9);assert(hangman_guess(&g,'a')&&g.remaining==8);assert(hangman_guess(&g,'b')&&g.status==HANGMAN_WIN);assert(!hangman_guess(&g,'x'));hangman_free(&g);hangman_init(&g,"a");for(int i=0;i<10;i++)assert(hangman_guess(&g,'x'));assert(g.status==HANGMAN_LOSE);hangman_free(&g);`,String.raw`void hangman_init(hangman*g,const char*w){(void)w;memset(g,0,sizeof *g);}bool hangman_guess(hangman*g,unsigned char c){(void)g;(void)c;return false;}void hangman_free(hangman*g){(void)g;}`);
